import{_ as e,o as a,c as i,a2 as s}from"./chunks/framework.D5wUhsuj.js";const k=JSON.parse('{"title":"PhyAgentOS 运行手册","description":"","frontmatter":{},"headers":[],"relativePath":"user_manual/README.md","filePath":"user_manual/README.md"}'),l={name:"user_manual/README.md"};function n(o,t,d,r,c,p){return a(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="phyagentos-运行手册" tabindex="-1">PhyAgentOS 运行手册 <a class="header-anchor" href="#phyagentos-运行手册" aria-label="Permalink to &quot;PhyAgentOS 运行手册&quot;">​</a></h1><p><a href="/docs/user_manual/README_en">English</a> · <a href="/docs/">文档索引</a></p><blockquote><p>版本：1.0.0</p></blockquote><h2 id="_1-运行模型" tabindex="-1">1. 运行模型 <a class="header-anchor" href="#_1-运行模型" aria-label="Permalink to &quot;1. 运行模型&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户/渠道 → AgentLoop → Forge task 与 Tool API tools</span></span>
<span class="line"><span>                              │</span></span>
<span class="line"><span>                       绑定调用或诊断 Query</span></span>
<span class="line"><span>                              ▼</span></span>
<span class="line"><span>                     ForgeToolClient</span></span>
<span class="line"><span>                              ▼</span></span>
<span class="line"><span>Gateway /tools → ToolInvocation → ToolEndpoint → Dora → 机器人/仿真器</span></span>
<span class="line"><span></span></span>
<span class="line"><span>绑定调用 → 不可变 Skill binding → AgentTask SQLite → verification/experience</span></span></code></pre></div><p>Gateway 负责执行，PAOS 负责用户任务聚合与语义判定。Skill Runtime 负责已安装 Bundle profile 的显式生命周期，但不替代 Gateway execution truth。</p><h2 id="_2-上线前检查" tabindex="-1">2. 上线前检查 <a class="header-anchor" href="#_2-上线前检查" aria-label="Permalink to &quot;2. 上线前检查&quot;">​</a></h2><h3 id="paos-主机" tabindex="-1">PAOS 主机 <a class="header-anchor" href="#paos-主机" aria-label="Permalink to &quot;PAOS 主机&quot;">​</a></h3><ul><li>已安装 Python 3.11/3.12 和目标 v1.0.0 环境；</li><li><code>paos status</code> 指向预期 config、workspace、model 和 provider；</li><li>Workspace、PAOS data paths 和 artifact paths 具备权限与磁盘空间；</li><li>允许非 <code>off</code> 任务时，Verification provider 凭据可用。</li></ul><h3 id="skill-runtime" tabindex="-1">Skill Runtime <a class="header-anchor" href="#skill-runtime" aria-label="Permalink to &quot;Skill Runtime&quot;">​</a></h3><ul><li>Skill Bundle metadata 包含 size 与 SHA-256，每个 Node lock 具有精确 SHA-256，并能解析为大小 明确的直接下载；</li><li>required binaries 可执行，required assets 存在，required environment 已设置；</li><li>Dora CLI v0.4.1 与 <code>dora-message</code> v0.7.0（当前 Forge Skill 兼容基线）已安装且位于 <code>PATH</code>，<code>dora --version</code> 同时指向预期版本；安装方式见 <a href="/docs/zh/02-user-manual#托管-skill-profile-所需的-dora-cli">用户手册</a>；</li><li>profile Gateway 地址没有被非托管进程占用。</li></ul><h3 id="forge-gateway" tabindex="-1">Forge Gateway <a class="header-anchor" href="#forge-gateway" aria-label="Permalink to &quot;Forge Gateway&quot;">​</a></h3><ul><li><code>GET /tools</code> 返回成功 object envelope；</li><li>required ToolSpecs 与 <code>/tools/{tool_id}/context</code> 存在并 ready；</li><li>Endpoint operation <code>max_concurrency</code> 符合机器人安全并发；</li><li>ToolSpec semantics、schema、binding 和 readiness 与已安装 Skill manifest 一致。</li></ul><h3 id="持久化" tabindex="-1">持久化 <a class="header-anchor" href="#持久化" aria-label="Permalink to &quot;持久化&quot;">​</a></h3><ul><li><code>.paos/agent_tasks</code>、<code>.paos/evolution</code>、Agent conversation history 与 Skill Runtime state 位于可靠存储；</li><li>轮转机器人证据时，备份和 retention 不删除 evolution 数据。</li></ul><h2 id="_3-启动与健康检查" tabindex="-1">3. 启动与健康检查 <a class="header-anchor" href="#_3-启动与健康检查" aria-label="Permalink to &quot;3. 启动与健康检查&quot;">​</a></h2><p>托管 Skill profile：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paos</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inspect</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">skill-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paos</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">skill-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">profil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paos</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">skill-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paos</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">other-skill-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">profil</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paos</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agent</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 或：paos gateway</span></span></code></pre></div><p><code>paos skill start</code> 会运行 <code>dora check</code>，本地 coordinator 和 daemon 尚未 ready 时调用 <code>dora up</code>；运维人员无需另行启动。Runtime 启动后，<code>dora check</code> 应当成功。</p><p>Runtime 健康要求持久化状态为 <code>running</code>、命名 Dora flow 存活、Gateway <code>/tools</code> 可用，并且 manifest 中每个 <code>required_tool</code> context ready。使用 <code>paos skill logs &lt;name&gt;</code> 查看生命周期和 Dora launch 日志。仅在没有非终态 AgentTask 时允许切换 Runtime；目标通过 ready 校验后才会 被选中，共用 Gateway 的目标启动失败时恢复先前 Runtime。长期运行的 Agent 会在下一次 activation 或 Tool call 前跟随持久化选择。</p><p>Agent 只使用该托管活动 Runtime 的 Gateway identity 与 URL。<code>paos status</code> 只检查本地配置； 实时 Tool readiness 应使用 <code>forge_tool_context</code>。</p><h2 id="_4-任务监控" tabindex="-1">4. 任务监控 <a class="header-anchor" href="#_4-任务监控" aria-label="Permalink to &quot;4. 任务监控&quot;">​</a></h2><p>分别记录以下 identity：</p><table tabindex="0"><thead><tr><th style="text-align:left;">Identity</th><th style="text-align:left;">责任方</th><th style="text-align:left;">用途</th></tr></thead><tbody><tr><td style="text-align:left;"><code>task_id</code></td><td style="text-align:left;">PAOS</td><td style="text-align:left;">用户任务聚合与验证</td></tr><tr><td style="text-align:left;"><code>binding_id</code></td><td style="text-align:left;">PAOS</td><td style="text-align:left;">冻结的 Skill 版本、Runtime 与 ToolSpec 集合</td></tr><tr><td style="text-align:left;"><code>revision_id</code></td><td style="text-align:left;">PAOS</td><td style="text-align:left;">只追加规划世代</td></tr><tr><td style="text-align:left;"><code>record_id</code></td><td style="text-align:left;">PAOS</td><td style="text-align:left;">一次绑定 Query、Action 或 Session record</td></tr><tr><td style="text-align:left;"><code>caller_id</code></td><td style="text-align:left;">PAOS</td><td style="text-align:left;">异步 admission 前持久化的身份</td></tr><tr><td style="text-align:left;"><code>invocation_id</code></td><td style="text-align:left;">Gateway</td><td style="text-align:left;">一次异步 Action 或 Session 生命周期</td></tr><tr><td style="text-align:left;"><code>attempt_id</code></td><td style="text-align:left;">Gateway</td><td style="text-align:left;">一次执行尝试</td></tr></tbody></table><p>使用 <code>forge_task_get(task_id)</code> 读取聚合状态与 Tool records；使用 对应 task-bound Action 或 Session status/result tool 读取执行事实。result endpoint 在 pending 时可以返回 HTTP 202。</p><p>任务状态：</p><table tabindex="0"><thead><tr><th style="text-align:left;">状态</th><th style="text-align:left;">运维含义</th></tr></thead><tbody><tr><td style="text-align:left;"><code>executing</code></td><td style="text-align:left;">规划或绑定 Tool calls 仍在继续。</td></tr><tr><td style="text-align:left;"><code>cancelling</code></td><td style="text-align:left;">已请求取消，但尚未证明物理停止。</td></tr><tr><td style="text-align:left;"><code>awaiting_replan</code></td><td style="text-align:left;">Verification 允许在 deadline 前追加有预算 PlanRevision。</td></tr><tr><td style="text-align:left;"><code>succeeded</code> / <code>failed</code> / <code>cancelled</code></td><td style="text-align:left;">PAOS 聚合终结；必要时仍独立检查 invocation facts。</td></tr></tbody></table><h2 id="_5-取消与停止" tabindex="-1">5. 取消与停止 <a class="header-anchor" href="#_5-取消与停止" aria-label="Permalink to &quot;5. 取消与停止&quot;">​</a></h2><p>取消单个 Action 时调用 <code>forge_tool_cancel_action(task_id, invocation_id)</code>，随后继续核对 status/result。 取消一个任务的全部 Action 时调用 <code>forge_task_cancel(task_id, reason)</code>，核对每个 invocation， 物理效果不确定时检查现场。Task cancel 同时停止 task-owned Session；shared 与 runtime-owned Session 保持各自独立生命周期。</p><p>绝不能把 <code>requested</code>、<code>accepted</code>、timeout 或 <code>unknown</code> 报告成物理停止证明。效果核实完成前 不要重试运动。</p><p>被追踪 invocation、Session 全部终结且无 task binding 后再停止托管 Runtime：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paos</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">skill-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p><code>--force</code> 只供已独立评估物理系统的运维人员使用。停止托管 Dora flow 前，它会尽力向已追踪 Action/Session 发出 cancel/stop，并把请求结果与未决引用写入 Runtime audit。请求被接受不证明 执行已终止，也不会改写 Gateway invocation result。</p><h2 id="_6-正常停机" tabindex="-1">6. 正常停机 <a class="header-anchor" href="#_6-正常停机" aria-label="Permalink to &quot;6. 正常停机&quot;">​</a></h2><ol><li>停止接纳新用户任务；</li><li>读取活动 AgentTask 并核对每个 Action/Session invocation；</li><li>Finalize，或 cancel 后 finalize AgentTask；</li><li>停止 PAOS channels 或 Agent；</li><li>停止 Skill Runtime profile；</li><li>只有没有其他 profile 使用时才停止共享基础设施。</li></ol><h2 id="_7-异常重启" tabindex="-1">7. 异常重启 <a class="header-anchor" href="#_7-异常重启" aria-label="Permalink to &quot;7. 异常重启&quot;">​</a></h2><p>PAOS 重启后，用已知 <code>task_id</code> 打开持久化 AgentTask。不要根据本地 intent 重建或重发 Action/Session。 查询每个已保存 <code>invocation_id</code>，根据 Gateway status/result 更新 record。Gateway 无法解析 invocation 时，将效果视为 unknown 并升级到物理现场检查。</p><p><code>paos skill status &lt;name&gt;</code> 会根据 Dora 与 Gateway health 核对 Runtime state。当 flow 或 Tool contexts 不可用时，它可将持久化 starting/running 改为 failed；重新启动前先诊断原 flow。</p><h2 id="_8-备份与磁盘管理" tabindex="-1">8. 备份与磁盘管理 <a class="header-anchor" href="#_8-备份与磁盘管理" aria-label="Permalink to &quot;8. 备份与磁盘管理&quot;">​</a></h2><p>停止 PAOS 后，将数据库、WAL/SHM 和引用目录一起备份：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;workspace&gt;/.paos/agent_tasks/tasks.sqlite3*</span></span>
<span class="line"><span>&lt;workspace&gt;/.paos/evolution/experience.sqlite3*</span></span>
<span class="line"><span>&lt;workspace&gt;/.paos/evolution/revisions/</span></span>
<span class="line"><span>&lt;workspace&gt;/artifacts/agent_tasks/</span></span>
<span class="line"><span>&lt;workspace&gt;/skills/</span></span></code></pre></div><p>还应按部署的 PAOS data-path 策略保留 installed Bundle/Node manifest、Runtime state 与生命周期 日志。Evidence retention 可以在验证后清理实体文件，但不能删除 task records、invocation references 或 evolution 历史。</p><h2 id="_9-故障分层" tabindex="-1">9. 故障分层 <a class="header-anchor" href="#_9-故障分层" aria-label="Permalink to &quot;9. 故障分层&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">层级</th><th style="text-align:left;">常见现象</th><th style="text-align:left;">首要处置</th></tr></thead><tbody><tr><td style="text-align:left;">Registry/install</td><td style="text-align:left;">Digest、size、manifest 或 lock 失败</td><td style="text-align:left;">修正可信 metadata 或 artifact，不绕过校验。</td></tr><tr><td style="text-align:left;">Runtime</td><td style="text-align:left;">Dora flow 或 Gateway health 不可用</td><td style="text-align:left;">检查 <code>paos skill status</code> 与 <code>logs</code>。</td></tr><tr><td style="text-align:left;">Tool context</td><td style="text-align:left;">Tool 缺失、未绑定或未 ready</td><td style="text-align:left;">检查 ToolSpec、Endpoint、frame 与 required profile。</td></tr><tr><td style="text-align:left;">Admission</td><td style="text-align:left;">HTTP/contract 失败</td><td style="text-align:left;">保留响应中已有 invocation ID，判断 Gateway 是否接纳。</td></tr><tr><td style="text-align:left;">Execution</td><td style="text-align:left;">pending、failed、cancelled 或 unknown</td><td style="text-align:left;">使用相同 invocation ID 核对；不确定时检查现场。</td></tr><tr><td style="text-align:left;">Evidence</td><td style="text-align:left;">before/after source 缺失</td><td style="text-align:left;">检查 source readiness 与 bundle errors，ToolResult 仍为权威。</td></tr><tr><td style="text-align:left;">Verification</td><td style="text-align:left;">invalid/inconclusive/service error</td><td style="text-align:left;">检查任务契约、evidence、provider 与 mode。</td></tr><tr><td style="text-align:left;">Evolution</td><td style="text-align:left;">reflection 或 promotion blocked</td><td style="text-align:left;">检查 evolution events；执行不受影响。</td></tr></tbody></table><h2 id="_10-运行验收清单" tabindex="-1">10. 运行验收清单 <a class="header-anchor" href="#_10-运行验收清单" aria-label="Permalink to &quot;10. 运行验收清单&quot;">​</a></h2><ul><li>[ ] Package 与 runtime version 均为 1.0.0；</li><li>[ ] 通用 Agent tools 与动态 MCP tools 仍注册；</li><li>[ ] 所需 Skill Bundle 与全部 Node artifact 校验通过；</li><li>[ ] 托管 Runtime ready，所有 Tool contexts 健康；</li><li>[ ] 诊断 Query 与绑定 Query/Action/Session 使用同一 Gateway Tool API；</li><li>[ ] 已覆盖 Action/Session admission、pending、terminal、cancel/stop、timeout、ownership 与 unknown；</li><li>[ ] 已覆盖单活动 AgentTask 与 PlanRevision recovery；</li><li>[ ] 绑定工作流完成 evidence 与任务级 verification；</li><li>[ ] Experience 记录 AgentTask、Skill activation、verification 与 invocation references；</li><li>[ ] 备份包含 AgentTask 与 evolution 持久化；</li><li>[ ] 具体 Skill/硬件验收单独记录确切 assets、nodes 与环境。</li></ul><h2 id="后续阅读" tabindex="-1">后续阅读 <a class="header-anchor" href="#后续阅读" aria-label="Permalink to &quot;后续阅读&quot;">​</a></h2><ul><li><a href="/docs/zh/02-user-manual">用户手册</a></li><li><a href="/docs/user_development_guide/COMMUNICATION">通信架构</a></li><li><a href="/docs/forge/README_zh">Forge Tool API 契约</a></li></ul>`,48)])])}const g=e(l,[["render",n]]);export{k as __pageData,g as default};
